contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token) public {
        // First call to addReward should always succeed for a fresh token
        bool firstReverted;
        try c.addReward(token) { firstReverted = false; } catch { firstReverted = true; }
        require(!firstReverted, "first addReward should succeed");

        // Now the token should be known: lastUpdateTime != 0
        // We can verify through public getter rewardData(token)
        (uint40 periodFinish1, uint216 rewardRate1, uint40 lastUpdate1, ) = c.rewardData(token);
        // lastUpdateTime must be non-zero after successful addReward
        require(lastUpdate1 != 0, "lastUpdateTime should be set");

        // Second call with the same token must revert because lastUpdateTime != 0
        bool secondReverted;
        try c.addReward(token) { secondReverted = false; } catch { secondReverted = true; }

        // The general rule: after a successful addReward for a token, any further
        // addReward call for the same token must revert.
        assert(secondReverted);
    }
}

