contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, address staker, uint256 stakeAmount, uint256 rewardAmount, uint256 elapsed) public payable {
        require(stakeAmount > 0, "stake amount must be positive");
        require(rewardAmount > 0, "reward amount must be positive");
        require(rewardToken != address(c), "reward token cannot be c");
        require(staker != address(0), "staker cannot be zero address");

        c.addReward(rewardToken);
        c.setRewardDistributor(address(this));

        uint256 stakeBalanceBefore = c.balanceOf(staker);
        uint256 totalSupplyBefore = c.totalSupply();

        uint256 rptBefore = c.rewardPerToken(rewardToken);
        uint256 earnedBefore = c.earned(staker, rewardToken);

        assert(rptBefore == 0 || totalSupplyBefore > 0);

        c.notifyRewardAmount(rewardToken, rewardAmount);

        uint256 rptAfterNotify = c.rewardPerToken(rewardToken);
        uint256 earnedAfterNotify = c.earned(staker, rewardToken);

        assert(rptAfterNotify >= rptBefore);
        assert(earnedAfterNotify >= earnedBefore);

        c.stakeFor(staker, stakeAmount);

        uint256 rptAfterStake = c.rewardPerToken(rewardToken);
        uint256 earnedAfterStake = c.earned(staker, rewardToken);

        assert(rptAfterStake >= rptAfterNotify);
        assert(earnedAfterStake >= earnedAfterNotify);

        c.getRewards(staker);

        uint256 claimableAfterGetRewards = c.claimableRewards(staker, rewardToken);
        uint256 balanceAfterGetRewards = c.balanceOf(staker);

        assert(claimableAfterGetRewards == 0);
        assert(balanceAfterGetRewards == stakeBalanceBefore + stakeAmount);

        uint256 totalRewardPaid;
        if (address(this).balance >= rewardAmount) {
            totalRewardPaid = rewardAmount;
        }

        assert(earnedAfterStake <= rewardAmount || rewardAmount == 0);
    }

    receive() external payable {}
}

