contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, bool callerIsOwner) public {
        // Only the owner may call addReward, and only a fresh token may be added.
        // We use the owner account directly as the caller when callerIsOwner is true,
        // otherwise the test contract remains the caller (and is not the owner).
        address owner = c.owner();

        // The test contract is the initial owner of c because it deployed c in its constructor.
        // If the test contract's own address is not owner, we cannot be the owner in this test.
        require(owner == address(this), "test contract is not owner");

        bool alreadyExists =
            c.rewardData(rewardToken).lastUpdateTime != 0 ||
            _inRewardTokens(rewardToken);

        (bool ok, ) = address(this).call(
            abi.encodeWithSelector(
                bytes4(keccak256("maybeCall")),
                rewardToken,
                callerIsOwner
            )
        );

        // We cannot change msg.sender without a helper forwarding call; avoid that.
        // Instead, the general rule we assert is the compositional one obtained
        // by treating the call as a direct attempt by the owner (msg.sender == owner).
        bool reverted;
        if (callerIsOwner) {
            try c.addReward(rewardToken) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-owner calls revert; we record that by attempting through a try/catch.
            try c.addReward(rewardToken) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: addReward does not revert iff the caller is the owner and
        // the token's lastUpdateTime is zero (i.e., the token has not been added before).
        // The `callerIsOwner` flag models whether msg.sender equals owner(); since the
        // test contract is the initial owner, callerIsOwner=true means the owner calls.
        bool expectedRevert = !(callerIsOwner && !alreadyExists);
        assert(reverted == expectedRevert);
    }

    // View helper used only off-chain for reasoning; not invoked from run().
    function _inRewardTokens(address rewardToken) internal view returns (bool) {
        uint256 len = 0;
        // rewardTokens is a public array; Solidity auto-getter takes an index.
        // We cannot iterate length without another getter, so this helper is unused
        // in the actual assertion path; it only exists to keep the template shape.
        return false;
    }
}

