contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken, uint256 amount) public {
        require(amount > 0, "amount must be positive");

        // Set up a usable reward token so notifyRewardAmount can succeed.
        // The test contract is the owner of c, so addReward is callable.
        c.addReward(rewardToken);

        uint256 beforeFinish = uint256(c.rewardPeriodFinish(rewardToken));

        // The test contract must be the reward distributor in order to notify.
        // Ensure it is set to this test contract; setRewardDistributor is onlyOwner.
        c.setRewardDistributor(address(this));

        // Notification requires the token transfer to succeed; give this contract
        // a real ERC20-like token by using the reward token as both staking and reward token
        // would be wrong. Instead, notifyRewardAmount will call safeTransferFrom on rewardToken.
        // We cannot rely on rewardToken being a token; but we can call it if the caller has tokens.
        // To keep the rule general, we only assert about the period finish update on success.
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterFinish = uint256(c.rewardPeriodFinish(rewardToken));

        // General rule: if the call to notifyRewardAmount did not revert, then the
        // reward period finish for that token was set to current block.timestamp + DURATION.
        // Since we cannot read block.timestamp directly in the assert, we assert the
        // observable consequence: after a successful notification, the finish time is
        // strictly greater than before and at least DURATION ahead of the previous finish
        // if the previous finish was in the future, or simply nonzero and in the future.
        // A correct implementation always sets periodFinish to block.timestamp + DURATION,
        // so for any successful call the new finish is at least the current timestamp + 1.
        // We cannot access block.timestamp in the assert, but we can assert that after a
        // successful notification the finish time is greater than the previous one by at least DURATION
        // when the previous finish was already in the past; otherwise it is at least previous finish.
        // The cleanest observable invariant: if not reverted, the reward period finish is
        // nonzero and strictly greater than before the call, and it is exactly DURATION seconds
        // after the current block timestamp. Since DURATION is public, we can use c.DURATION().
        uint256 duration = c.DURATION();

        // If the call succeeded, the new finish must equal block.timestamp + DURATION.
        // We can check that it is greater than or equal to the current timestamp + DURATION - 1
        // or similar, but without block.timestamp we cannot check equality. However, we can
        // use the fact that the previous finish was set by addReward to be block.timestamp
        // and after successful notify the new finish should be previousFinish + DURATION if
        // the previous finish was in the past, or block.timestamp + DURATION otherwise.
        // Since addReward set lastUpdateTime and periodFinish to current block.timestamp,
        // and notifyRewardAmount is called in the same transaction, the previous finish
        // is exactly block.timestamp. Therefore the new finish must be exactly oldFinish + DURATION.
        // This holds because block.timestamp is unchanged within the transaction.
        assert(reverted || afterFinish == beforeFinish + duration);
    }

    receive() external payable {}
}

