        // simulate here; instead assert that when called by the actual migrator (this contract),
        // the migrator guard is satisfied and does not itself cause failure when the staker has
        // no balance (amount 0) path is prevented by other requires. So we assert the equivalent
        // observable: the call either succeeded, or if it reverted it was not because of the
        // migrator guard, which is only observable by the fact that migrator equals msg.sender.
        bool calledByMigrator = (address(this) == c.migrator());
        bool callerCheckSatisfied = calledByMigrator;
        assert(callerCheckSatisfied || reverted);
    }
