        c = _c;
    }

    function run(address staker, uint256 amount, address newMigrator) public {
        // Set a known migrator. Even if newMigrator == address(this), it's fine.
        c.setMigrator(newMigrator);

        // Read observable pre-state.
        uint256 balBefore = c.balanceOf(staker);
        uint256 totalBefore = c.totalSupply();

        // Decide the call: try migrateWithdraw(staker, amount).
        bool reverted;
        try c.migrateWithdraw(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The call must succeed iff caller (this contract) is the migrator and the staker has enough stake.
        bool shouldSucceed = (address(this) == newMigrator) && (balBefore >= amount) && (amount > 0);
        // For the successful path, balance must decrease by amount and totalSupply must decrease by amount.
        if (!reverted) {
            assert(c.balanceOf(staker) == balBefore - amount);
            assert(c.totalSupply() == totalBefore - amount);
        } else {
            assert(!shouldSucceed);
        }
        // The general rule: reverts exactly when it should not succeed.
        assert(reverted == !shouldSucceed);
    }
}

