        uint256 beforeTotal = c.totalSupply();

        // Try the deciding call and record whether it reverted.
        bool reverted;
        try c.stakeFor(_for, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the post-call total supply through the public getter.
        uint256 afterTotal = c.totalSupply();

        if (_amount == 0) {
            // A zero stake must always revert and leave state unchanged.
            assert(reverted && afterTotal == beforeTotal);
        } else {
            // A nonzero stake must not revert and must increase total supply by exactly amount.
            assert(!reverted && afterTotal == beforeTotal + _amount);
        }
    }
}

