    }

    function run(address caller, address token, uint256 amount, bool preAdd) public {
        // If preAdd is true, add the reward token (onlyOwner = this test contract) so it is known.
        // If false, leave it unknown, which makes notifyRewardAmount revert with "unknown reward token".
        if (preAdd) {
            c.addReward(token);
        }

        // Determine whether the owner of c is the test contract, so we can set the distributor to caller.
        // Since we deployed c, owner() == address(this) at construction time.
        address distributorBefore = c.rewardDistributor();

        // Set c's distributor to `caller` if allowed; if not (e.g., already changed), leave as is.
        bool setDistributorOk;
        try c.setRewardDistributor(caller) {
            setDistributorOk = true;
        } catch {
            setDistributorOk = false;
        }

        // Caller is considered the distributor only if the set succeeded and caller is nonzero,
        // or if caller already equals the existing distributor.
        bool callerIsDistributor = (setDistributorOk && caller != address(0)) || (caller == distributorBefore && caller != address(0));

        // Token is known iff preAdd succeeded (addReward would have succeeded since onlyOwner = test).
        bool tokenIsKnown = preAdd;

        bool reverted;
        try c.notifyRewardAmount(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: notifyRewardAmount completes (does not revert) exactly when the caller is
        // the current rewardDistributor, the amount is positive, and the reward token is known.
        bool expectedSuccess = (callerIsDistributor && amount > 0 && tokenIsKnown);

        assert(reverted != expectedSuccess);
    }

    receive() external payable {}
}

