        // Now read the owner via the public entry point.
        address currentOwner = c.owner();

        // General rule: the owner() call completes (it is a view, cannot revert) and
        // returns the address that was initially the owner when c was constructed.
        // Since this contract deployed c, that initial owner is address(this).
