        // which reverts). If it reverted, owner remains address(this).
        // A faulty version that returns something else or reverts would break this.
        assert(currentOwner == address(this) || (!reverted && currentOwner == newOwner && newOwner != address(0)));
    }

    receive() external payable {}
}

