    constructor(C _c) {
        c = _c;
    }

    function run(address rewardToken) public {
        require(rewardToken != address(0), "zero reward token");

        c.addReward(rewardToken);
        uint40 afterFirstFinish = c.rewardPeriodFinish(rewardToken);

        bool secondReverted;
        try c.addReward(rewardToken) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint40 afterSecondFinish = c.rewardPeriodFinish(rewardToken);

        assert(secondReverted && afterSecondFinish == afterFirstFinish);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token) public payable {
        require(token != address(0));

        uint256 ts = c.totalSupply();
        bool reverted;
        uint256 rpt;
        try c.rewardPerToken(token) returns (uint256 v) {
            rpt = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint40 periodFinish, uint216 rewardRate, uint40 lastUpdateTime, uint216 rewardPerTokenStored) = c.rewardData(token);

        if (!reverted && ts == 0) {
            assert(rpt == uint256(rewardPerTokenStored));
        } else if (!reverted) {
            assert(rpt >= uint256(rewardPerTokenStored));
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

