contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address rewardToken) public payable {
        // Fresh C, so we must add the reward token first.
        c.addReward(rewardToken);

        // Record the mapping getter value before the call under test.
        (, , , ) = c.rewardData(rewardToken); // this is a read, but destructuring a struct tuple isn't allowed as a standalone statement
        // Actually read the mapping tuple explicitly:
        (uint40 pf0, uint216 rr0, uint40 lu0, uint216 rpts0) = c.rewardData(rewardToken);
        uint40 finish0 = c.rewardPeriodFinish(rewardToken);
        uint40 finish1 = c.rewardPeriodFinish(rewardToken);

        // General rule: rewardPeriodFinish returns exactly the periodFinish stored in rewardData,
        // and repeated calls return the same value as long as state is unchanged.
        assert(finish1 == finish0 && finish1 == pf0);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address rewardToken) public payable {
        // Fresh C: register the reward token so rewardData has a defined periodFinish.
        c.addReward(rewardToken);

        // Read the mapping value (public getter) and the dedicated getter.
        (uint40 pf, , , ) = c.rewardData(rewardToken);
        uint40 finish = c.rewardPeriodFinish(rewardToken);

        // General rule: the getter agrees with the stored periodFinish, and it is the
        // timestamp-based finish used by addReward (block.timestamp at add time).
        assert(finish == pf && finish != 0);
    }

    receive() external payable {}
}

