contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, address token) public view {
        require(account != address(0), "zero account");

        uint256 balance = c.balanceOf(account);
        uint256 rewardPerTokenVal = c.rewardPerToken(token);
        uint256 paid = c.userRewardPerTokenPaid(account, token);
        uint256 claimable = c.claimableRewards(account, token);

        bool reverted;
        uint256 earnedVal;
        try c.earned(account, token) returns (uint256 v) {
            earnedVal = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(earnedVal == (balance * (rewardPerTokenVal - paid)) / 1e18 + claimable);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

