contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _for, uint256 _amount) public payable {
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(_for);

        bool reverted;
        try c.stakeFor(_for, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (_amount == 0) {
            assert(reverted);
            assert(c.totalSupply() == totalBefore);
            assert(c.balanceOf(_for) == balBefore);
        } else {
            assert(!reverted);
            assert(c.totalSupply() == totalBefore + _amount);
            assert(c.balanceOf(_for) == balBefore + _amount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
