        uint256 balBefore = c.balanceOf(_for);

        bool reverted;
        try c.stakeFor(_for, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            (_amount == 0 && reverted && c.totalSupply() == totalBefore && c.balanceOf(_for) == balBefore) ||
            (_amount > 0 && !reverted && c.totalSupply() == totalBefore + _amount && c.balanceOf(_for) == balBefore + _amount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _for, uint256 _amount) public payable {
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(_for);
        uint256 callerTokenBalance = c.stakingToken().balanceOf(address(this));
        uint256 allowance = c.stakingToken().allowance(address(this), address(c));

        bool reverted;
        try c.stakeFor(_for, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool mustRevert = (_amount == 0) || (_amount > callerTokenBalance) || (_amount > allowance);

        assert(reverted == mustRevert);

        if (!reverted) {
            assert(c.totalSupply() == totalBefore + _amount);
            assert(c.balanceOf(_for) == balBefore + _amount);
        } else {
            assert(c.totalSupply() == totalBefore);
            assert(c.balanceOf(_for) == balBefore);
        }
    }

    receive() external payable {}
}

