contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 _amount) public payable {
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        if (_amount > 0) {
            address(c.stakingToken()).call(abi.encodeWithSignature("transfer(address,uint256)", address(c), _amount));
        }

        bool zero = (_amount == 0);
        bool reverted;
        try c.stakeFor(address(this), _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (zero) {
            assert(reverted && c.totalSupply() == totalBefore && c.balanceOf(address(this)) == balBefore);
        } else {
            assert(!reverted && c.totalSupply() == totalBefore + _amount && c.balanceOf(address(this)) == balBefore + _amount);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address token, uint256 amount) public {
        address distributor = c.rewardDistributor();
        bool isDistributor = (distributor == address(this));
        uint256 balanceBefore = IERC20(token).balanceOf(address(c));
        bool reverted;
        try c.notifyRewardAmount(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (!isDistributor || amount == 0) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(IERC20(token).balanceOf(address(c)) == balanceBefore + amount);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, uint256 amount) public {
        address distributor = c.rewardDistributor();
        uint256 lastUpdateTime = c.rewardData(token);
        bool tokenKnown = (lastUpdateTime != 0);
        uint256 balanceBefore = IERC20(token).balanceOf(address(c));
        bool reverted;
        try c.notifyRewardAmount(token, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool shouldRevert = (distributor != address(this)) || (!tokenKnown) || (amount == 0);
        assert(reverted == shouldRevert && (reverted || IERC20(token).balanceOf(address(c)) == balanceBefore + amount));
    }
}

