contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount) public {
        c.setMigrator(address(this));

        uint256 balBefore = c.balanceOf(staker);

        bool reverted;
        try c.migrateWithdraw(staker, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (amount == 0 || amount > balBefore) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(c.balanceOf(staker) == balBefore - amount);
        }
    }
